def clap_error(msg, usage=True):
    print(f"error: {msg}", file=sys.stderr)
    print("", file=sys.stderr)
    if usage:
        print("Usage: executable [OPTIONS]", file=sys.stderr)
        print("", file=sys.stderr)
    print("For more information, try '--help'.", file=sys.stderr)
    sys.exit(2)

def parse_args(argv):
    opts = Opts()
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == '--':
            if i + 1 < len(argv):
                clap_error(f"unexpected argument '{argv[i+1]}' found")
            break
        if a.startswith('--') and len(a) > 2:
            body = a[2:]
            val_inline = None
            if '=' in body:
                body, val_inline = body.split('=', 1)
            if body not in LONG_MAP:
                clap_error(f"unexpected argument '--{body}' found")
            attr, needs = LONG_MAP[body]
            if needs:
                if val_inline is not None:
                    val = val_inline
                else:
                    if i + 1 >= len(argv):
                        # clap uses canonical long spelling for aliases
                        name = body
                        placeholder = '<file>' if body == 'file' else f'<{body}>'
                        print(f"error: a value is required for '--{name} {placeholder}' but none was supplied", file=sys.stderr)
                        print("", file=sys.stderr)
                        print("For more information, try '--help'.", file=sys.stderr)
                        sys.exit(2)
                    i += 1
                    val = argv[i]
                setattr(opts, attr, val)
            else:
                if val_inline is not None:
                    clap_error(f"unexpected value '{val_inline}' for '--{body}' found")
                setattr(opts, attr, True)
        elif a.startswith('-') and a != '-':
            cluster = a[1:]
            j = 0
            while j < len(cluster):
                ch = cluster[j]
                if ch in SHORT_VAL:
                    attr = SHORT_VAL[ch]
                    if j + 1 < len(cluster):
                        val = cluster[j+1:]
                        j = len(cluster)
                    else:
                        if i + 1 >= len(argv):
                            long = 'file' if ch == 'f' else 'output'
                            ph = '<file>' if ch == 'f' else '<output>'
                            print(f"error: a value is required for '--{long} {ph}' but none was supplied", file=sys.stderr)
                            print("", file=sys.stderr)
                            print("For more information, try '--help'.", file=sys.stderr)
                            sys.exit(2)
                        i += 1
                        val = argv[i]
                    setattr(opts, attr, val)
