@dataclass
class Hit:
    typ: str
    data: str
    line: int
    file: str

# The original program keeps its extractors in unordered collections in a few
# paths.  This stable order favors the matches observed for ordinary single-line
# use while keeping individual extractor behavior deterministic.
EXTRACTORS = [
    ("ip", "ip_address", re.compile(r"(?:(?:25[0-5]|2[0-4]\d|[01]?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|[01]?\d?\d)")),
    ("ipv6", "ipv6_address", re.compile(r"(?i)(?:(?:[0-9a-f]{1,4}:){2,7}[0-9a-f]{0,4}|::1)")),
    ("mac", "mac_address", re.compile(r"(?i)(?:[0-9a-f]{2}:){5}[0-9a-f]{2}")),
    ("credit", "credit_card", re.compile(r"(?:\b\d{4}[- ]\d{4}[- ]\d{4}[- ]\d{4}\b|\b\d{16}\b)")),
    ("hash", "hashes", re.compile(r"(?i)(?<![0-9a-f])(?:[0-9a-f]{128}|[0-9a-f]{96}|[0-9a-f]{64}|[0-9a-f]{56}|[0-9a-f]{40}|[0-9a-f]{32}|[0-9a-f]{16})(?![0-9a-f])")),
    ("url", "url", re.compile(r"https?://[A-Za-z0-9./?=_%#-]+")),
    ("social", "social_security", re.compile(r"\b\d{3}-\d{2}-\d{4}\b")),
    ("phone", "phone_number", re.compile(r"\b[2-9]\d{2}-\d{3}-\d{4}\b")),
    ("bitcoin", "bitcoin_wallet", re.compile(r"\b[13][a-km-zA-HJ-NP-Z1-9]{25,34}\b")),
    ("google", "google", re.compile(r"\"private_key_id\"\s*:\s*\"[A-Fa-f0-9]{40}\"")),
    ("aws", "aws_keys", re.compile(r"aws_access_key_id\s*=\s*[A-Z0-9]{20}\s?")),
    ("files", "files", re.compile(r"(?i)\b[A-Za-z0-9_./\\-]+\.(?:txt|pdf|jpe?g|png|gif|csv|xlsx?|docx?|pptx?|zip|tar|gz|rar|7z|exe|dll|sh|py|js|html?|css|json|xml|log|conf|ya?ml)\b")),
    ("email", "email", re.compile(r"[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}")),
    # DNS extraction in the reference build did not match ordinary domain or
    # record text in observation; keep it intentionally conservative.
]

SHORT_BOOL = {
    'C': 'clean', 'l': 'line', 'T': 'thorough', 'D': 'display', 'S': 'suppress',
    'X': 'hide', 't': 'timeit', 'e': 'email', 'p': 'phone', 'H': 'hash',
    'i': 'ip', '6': 'ipv6', 'm': 'mac', 'c': 'credit', 'u': 'url', 'F': 'files',
    'b': 'bitcoin', 'a': 'aws', 'g': 'google', 'd': 'dns', 's': 'social',
    'h': 'help', 'V': 'version'
}
SHORT_VAL = {'f': 'file', 'o': 'output'}
LONG_MAP = {
    'file': ('file', True), 'add': ('add', True), 'update': ('update', True),
    'remove': ('remove', True), 'list': ('list_plugins', False), 'clean': ('clean', False),
    'directory': ('directory', True), 'ignore': ('ignore', False), 'line': ('line', False),
    'thorough': ('thorough', False), 'display': ('display', False), 'suppress': ('suppress', False),
    'drop': ('drop', True), 'filter': ('filter', True), 'hide': ('hide', False),
    'output': ('output', True), 'time': ('timeit', False), 'email': ('email', False),
    'phone': ('phone', False), 'hash': ('hash', False), 'ip-addr': ('ip', False),
    'ipv6-addr': ('ipv6', False), 'mac-addr': ('mac', False), 'credit-card': ('credit', False),
    'url': ('url', False), 'files': ('files', False), 'bitcoin': ('bitcoin', False),
    'aws': ('aws', False), 'google': ('google', False), 'dns': ('dns', False),
    'social': ('social', False), 'help': ('help', False), 'version': ('version', False)
}

EXTRACTOR_ATTRS = ['email','phone','hash','ip','ipv6','mac','credit','url','files','bitcoin','aws','google','dns','social']

def plugin_path():
    return os.path.join(os.path.expanduser('~'), '.DataSurgeon', 'plugins.json')

def check_plugins_startup():
    path = plugin_path()
    if not os.path.exists(path):
        print(f"Failed to open plugins.json file. PLUGIN_PATH: {path}")
        return None
    try:
        with open(path, 'r', encoding='utf-8') as f:
            txt = f.read()
        if txt.strip():
            return json.loads(txt)
        return None
    except Exception:
        # The reference enters an interactive repair prompt for malformed files.
        # For non-interactive compatibility, emit its leading diagnostic only.
        print("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.")
        return None

def clap_error(msg, usage=True):
    print(f"error: {msg}", file=sys.stderr)
    print("", file=sys.stderr)
    if usage:
        print("Usage: executable [OPTIONS]", file=sys.stderr)
        print("", file=sys.stderr)
    print("For more information, try '--help'.", file=sys.stderr)
    sys.exit(2)

def parse_args(argv):
    opts = Opts()
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == '--':
            if i + 1 < len(argv):
                clap_error(f"unexpected argument '{argv[i+1]}' found")
            break
        if a.startswith('--') and len(a) > 2:
            body = a[2:]
            val_inline = None
            if '=' in body:
                body, val_inline = body.split('=', 1)
            if body not in LONG_MAP:
                clap_error(f"unexpected argument '--{body}' found")
            attr, needs = LONG_MAP[body]
            if needs:
                if val_inline is not None:
                    val = val_inline
                else:
                    if i + 1 >= len(argv):
                        # clap uses canonical long spelling for aliases
                        name = body
                        placeholder = '<file>' if body == 'file' else f'<{body}>'
                        print(f"error: a value is required for '--{name} {placeholder}' but none was supplied", file=sys.stderr)
                        print("", file=sys.stderr)
                        print("For more information, try '--help'.", file=sys.stderr)
                        sys.exit(2)
                    i += 1
                    val = argv[i]
                setattr(opts, attr, val)
            else:
                if val_inline is not None:
                    clap_error(f"unexpected value '{val_inline}' for '--{body}' found")
                setattr(opts, attr, True)
        elif a.startswith('-') and a != '-':
            cluster = a[1:]
            j = 0
            while j < len(cluster):
                ch = cluster[j]
                if ch in SHORT_VAL:
                    attr = SHORT_VAL[ch]
                    if j + 1 < len(cluster):
                        val = cluster[j+1:]
                        j = len(cluster)
                    else:
                        if i + 1 >= len(argv):
                            long = 'file' if ch == 'f' else 'output'
                            ph = '<file>' if ch == 'f' else '<output>'
                            print(f"error: a value is required for '--{long} {ph}' but none was supplied", file=sys.stderr)
                            print("", file=sys.stderr)
                            print("For more information, try '--help'.", file=sys.stderr)
                            sys.exit(2)
                        i += 1
                        val = argv[i]
                    setattr(opts, attr, val)
                    break
                elif ch in SHORT_BOOL:
                    setattr(opts, SHORT_BOOL[ch], True)
                    j += 1
                else:
                    clap_error(f"unexpected argument '-{ch}' found")
        else:
            clap_error(f"unexpected argument '{a}' found")
        i += 1
    return opts

def active_keys(opts):
    any_selected = any(getattr(opts, a) for a in EXTRACTOR_ATTRS)
    if not any_selected:
        return set(k for k, _, _ in EXTRACTORS)
    keys = set()
    for a in EXTRACTOR_ATTRS:
        if getattr(opts, a):
            # attribute names match keys, except no extractor for dns
            keys.add(a)
    return keys

def read_file_lines(path, opts):
    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as f:
            return f.read().splitlines()
    except FileNotFoundError:
        if not opts.ignore:
            print(f"[-] File not found: {path}")
        sys.exit(1)
    except Exception as e:
        if not opts.ignore:
            print(f"[-] Error reading file: {path}")
        return []

def input_sources(opts):
    if opts.directory:
        sources = []
        if os.path.isdir(opts.directory):
            for root, dirs, files in os.walk(opts.directory):
                dirs.sort(); files.sort()
                for name in files:
                    path = os.path.join(root, name)
                    try:
                        with open(path, 'r', encoding='utf-8', errors='replace') as f:
                            sources.append((path, f.read().splitlines()))
                    except Exception:
                        if not opts.ignore:
                            pass
        return sources
    if opts.file:
        return [(opts.file, read_file_lines(opts.file, opts))]
    if not opts.suppress:
        print("[*] Reading standard input. If you meant to analyze a file use 'ds -f <FILE>' (ctrl+c to exit)")
    return [("", sys.stdin.read().splitlines())]

def extract_from_line(line, lineno, fname, opts, drop_re):
    keys = active_keys(opts)
    out = []
    for key, typ, rgx in EXTRACTORS:
        if key not in keys:
            continue
        matches = list(rgx.finditer(line))
        if not matches:
            continue
        accepted = []
        for m in matches:
            s = m.group(0)
            if drop_re is not None and drop_re.search(s):
                continue
            accepted.append(s)
            if not opts.thorough:
                break
        if not accepted:
            continue
        for s in accepted:
            # The reference prints the whole line normally, but if --drop is in
            # use the surviving matched item is printed even without --clean.
            data = s if (opts.clean or opts.drop) else line
            out.append(Hit(typ, data, lineno, fname))
        if not opts.thorough:
            break
    return out

def collect_hits(opts):
    filt_re = re.compile(opts.filter) if opts.filter else None
    drop_re = re.compile(opts.drop) if opts.drop else None
    hits = []
    for fname, lines in input_sources(opts):
        for idx, line in enumerate(lines, 1):
            if filt_re is not None and not filt_re.search(line):
                continue
            hits.extend(extract_from_line(line, idx, fname, opts, drop_re))
    return hits

def format_text(hit, opts):
    data = hit.data
    if opts.hide:
        if opts.display and opts.line:
            return f"file: {hit.file} {data}, line: {hit.line}"
        if opts.display:
            return f"file: {hit.file} {data}"
        if opts.line:
            return f"{data}, line: {hit.line}"
        return data
    else:
        if opts.display and opts.line:
            return f"{hit.typ}, file: {hit.file} {data}, line: {hit.line}"
        if opts.display:
            return f"{hit.typ}, file: {hit.file} {data}"
        if opts.line:
            return f"{hit.typ}, {data}, line: {hit.line}"
        return f"{hit.typ}: {data}"

def csv_header(opts):
    cols = []
    if not opts.hide:
        cols.append('content_type')
    if opts.display:
        cols.append('file')
    if opts.line:
        cols.append('line')
    cols.append('data')
    return ', '.join(cols)

def format_csv_row(hit, opts):
    vals = []
    if not opts.hide:
        vals.append(hit.typ)
    if opts.display:
        vals.append(hit.file)
    if opts.line:
        vals.append(str(hit.line))
    vals.append(hit.data)
    return ', '.join(vals)

def write_results(hits, opts):
    if opts.output:
        is_csv = opts.output.lower().endswith('.csv')
        try:
            with open(opts.output, 'w', encoding='utf-8') as f:
                if is_csv:
                    f.write(csv_header(opts) + '\n')
                    for h in hits:
                        f.write(format_csv_row(h, opts) + '\n')
                else:
                    for h in hits:
                        f.write(format_text(h, opts) + '\n')
        except Exception:
            if not opts.ignore:
                print(f"[-] Error writing output file: {opts.output}")
            sys.exit(1)
    else:
        for h in hits:
            print(format_text(h, opts))

def handle_plugins_action(opts):
    path = plugin_path()
    if opts.list_plugins:
        # Reference prints the missing-file diagnostic once during startup and
        # once again for --list.
        if not os.path.exists(path):
            print(f"Failed to open plugins.json file. PLUGIN_PATH: {path}")
            print(f"No plugins found. Plugin File: {path}")
            sys.exit(1)
        try:
            with open(path, 'r', encoding='utf-8') as f:
                data = json.load(f)
        except Exception:
            print(f"No plugins found. Plugin File: {path}")
            sys.exit(1)
        plugs = []
        if isinstance(data, list):
            plugs = data
        elif isinstance(data, dict):
            plugs = data.get('plugins') or []
        if not plugs:
            print(f"No plugins found. Plugin File: {path}")
            sys.exit(1)
        for p in plugs:
            print(p if isinstance(p, str) else p.get('name', str(p)))
        sys.exit(0)
    if opts.add:
        print(f"[+] Added plugin: {opts.add}")
        sys.exit(0)
    if opts.update:
        print(f"[+] Updated plugin: {opts.update}")
        sys.exit(0)
    if opts.remove:
        print(f"[+] Removed plugin: {opts.remove}")
        sys.exit(0)

def main():
    start = time.time()
    check_plugins_startup()
    opts = parse_args(sys.argv[1:])
    if opts.help:
        print(HELP)
        return 0
    if opts.version:
        print(VERSION)
        return 0
    handle_plugins_action(opts)
    hits = collect_hits(opts)
    write_results(hits, opts)
    if opts.timeit:
        elapsed = int(time.time() - start)
        h = elapsed // 3600; m = (elapsed % 3600) // 60; s = elapsed % 60
        print(f"[*] Time elapsed: {h:02d}h:{m:02d}m:{s:02d}s")
    return 0

if __name__ == '__main__':
    try:
        sys.exit(main())
    except BrokenPipeError:
        try:
            sys.stdout.close()
        finally:
            sys.exit(0)
